import{_ as e,c as r,o as i,ah as n}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"28、【大過】 巽下兌上","description":"溫公易說 - 28、【大過】 巽下兌上","frontmatter":{"title":"28、【大過】 巽下兌上","description":"溫公易說 - 28、【大過】 巽下兌上"},"headers":[],"relativePath":"classics/wengong/029.md","filePath":"classics/wengong/029.md"}'),l={name:"classics/wengong/029.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_28、【大過】-巽下兌上" tabindex="-1">28、【大過】 巽下兌上 <a class="header-anchor" href="#_28、【大過】-巽下兌上" aria-label="Permalink to “28、【大過】 巽下兌上”">​</a></h1><h3 id="彖曰-大過-大者過也。棟橈-本末弱也。剛過而中-巽而說-行利有攸往-乃亨。大過之時-大矣哉。" tabindex="-1">彖曰：大過，大者過也。棟橈，本末弱也。剛過而中，巽而說，行利有攸往，乃亨。大過之時，大矣哉。 <a class="header-anchor" href="#彖曰-大過-大者過也。棟橈-本末弱也。剛過而中-巽而說-行利有攸往-乃亨。大過之時-大矣哉。" aria-label="Permalink to “彖曰：大過，大者過也。棟橈，本末弱也。剛過而中，巽而說，行利有攸往，乃亨。大過之時，大矣哉。”">​</a></h3><p>大過者何？大者陽也。陽之過差者也。陽之所以過差者奈何？陽當居外以衛陰，陰當居內以佐陽。今大過多陽而居內，小過多陰而居外，此其所以為過也。然則彖曰剛過而中，巽而說，行利有攸往，乃亨何也？大過者，剛之過也。有攸往者，猶雲有為而然者也。夫剛過而不得其中，又不以巽說行之，其志非以有為也，茍求過人而已矣。如是則何以得亨乎？故大過之所以得亨者，此數德故也。君子或為過人之行者，將以有為也，非道之常也。故曰利有攸往，乃亨。</p><h3 id="象曰-澤滅木-大過。君子以獨立不懼-遁世無悶。" tabindex="-1">象曰：澤滅木，大過。君子以獨立不懼，遁世無悶。 <a class="header-anchor" href="#象曰-澤滅木-大過。君子以獨立不懼-遁世無悶。" aria-label="Permalink to “象曰：澤滅木，大過。君子以獨立不懼，遁世無悶。”">​</a></h3><h3 id="初六-藉用白茅-無咎-象曰-藉用白茅-柔在下也。" tabindex="-1">初六：藉用白茅，無咎 象曰：藉用白茅，柔在下也。 <a class="header-anchor" href="#初六-藉用白茅-無咎-象曰-藉用白茅-柔在下也。" aria-label="Permalink to “初六：藉用白茅，無咎 象曰：藉用白茅，柔在下也。”">​</a></h3><h3 id="九二-枯楊生稊-老夫得其女妻-無不利-象曰-老夫女妻-過以相與也。" tabindex="-1">九二：枯楊生稊，老夫得其女妻，無不利 象曰：老夫女妻，過以相與也。 <a class="header-anchor" href="#九二-枯楊生稊-老夫得其女妻-無不利-象曰-老夫女妻-過以相與也。" aria-label="Permalink to “九二：枯楊生稊，老夫得其女妻，無不利 象曰：老夫女妻，過以相與也。”">​</a></h3><h3 id="九三-棟橈-兇-象曰-棟橈之兇-不可有輔也。" tabindex="-1">九三：棟橈，兇 象曰：棟橈之兇，不可有輔也。 <a class="header-anchor" href="#九三-棟橈-兇-象曰-棟橈之兇-不可有輔也。" aria-label="Permalink to “九三：棟橈，兇 象曰：棟橈之兇，不可有輔也。”">​</a></h3><h3 id="九四-棟隆-吉。有它吝-象曰-棟隆之吉-不橈乎下也。" tabindex="-1">九四：棟隆，吉。有它吝 象曰：棟隆之吉，不橈乎下也。 <a class="header-anchor" href="#九四-棟隆-吉。有它吝-象曰-棟隆之吉-不橈乎下也。" aria-label="Permalink to “九四：棟隆，吉。有它吝 象曰：棟隆之吉，不橈乎下也。”">​</a></h3><h3 id="九五-枯楊生華-老婦得其士夫-無咎-無譽-象曰-枯楊生華-何可久也。老婦士夫-亦可醜也。" tabindex="-1">九五：枯楊生華，老婦得其士夫，無咎，無譽 象曰：枯楊生華，何可久也。老婦士夫，亦可醜也。 <a class="header-anchor" href="#九五-枯楊生華-老婦得其士夫-無咎-無譽-象曰-枯楊生華-何可久也。老婦士夫-亦可醜也。" aria-label="Permalink to “九五：枯楊生華，老婦得其士夫，無咎，無譽 象曰：枯楊生華，何可久也。老婦士夫，亦可醜也。”">​</a></h3><h3 id="上六-過涉滅頂-兇-無咎-象曰-過涉之兇-不可咎也。" tabindex="-1">上六：過涉滅頂，兇，無咎 象曰：過涉之兇，不可咎也。 <a class="header-anchor" href="#上六-過涉滅頂-兇-無咎-象曰-過涉之兇-不可咎也。" aria-label="Permalink to “上六：過涉滅頂，兇，無咎 象曰：過涉之兇，不可咎也。”">​</a></h3>',10)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
